                                    visited.add(f"{nr},{nc}")
                                    queue.append((nr,nc))

                    result[key] = {'color': color, 'size': len(visited), 'neighbors': []}

        # Now find neighbors
        for r in range(len(grid)):
            for c in range(len(grid[r])):
                if grid[r][c] != bg:
                    key = (r, c)
                    info = result.get(key)
                    if info:
