                    comp_pixels.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < n_rows and 0 <= nc < n_cols:
                            key = f"{nr},{nc}"
                            if key not in visited and grid[nr][nc] == color:
